    Bug 803994 - If UNAVAILABLE response occurs at imap login, show server response & don't prompt for password. r=mkmelin

    This rebases and updates the patch by David Lechner from 12 years ago using additional information from
    https://bugzilla.mozilla.org/show_bug.cgi?id=1602375#c6

    Differential Revision: https://phabricator.services.mozilla.com/D186683

diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index 81b873ea1ac..2899ec6eaa0 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -8625,6 +8625,12 @@ bool nsImapProtocol::TryToLogon() {
     loginSucceeded = NS_SUCCEEDED(rv);

     if (!loginSucceeded) {
+      // If server gave reason for authentication failure as [UNAVAILABLE]
+      // then we skip authentication retries, etc. The user will be notified by
+      // pop-up with the reason, provided by the server, as to why it's
+      // unavailable, e.g., too many connection to the server.
+      if (GetServerStateParser().fServerUnavailable) break;
+
       MOZ_LOG(IMAP, LogLevel::Debug, ("authlogin failed"));
       MarkAuthMethodAsFailed(m_currentAuthMethod);
       rv = ChooseAuthMethod();  // change m_currentAuthMethod to try other one
diff --git a/mailnews/imap/src/nsImapServerResponseParser.cpp b/mailnews/imap/src/nsImapServerResponseParser.cpp
index 289c5840eac..9550e78322d 100644
--- a/mailnews/imap/src/nsImapServerResponseParser.cpp
+++ b/mailnews/imap/src/nsImapServerResponseParser.cpp
@@ -74,6 +74,7 @@ nsImapServerResponseParser::nsImapServerResponseParser(
   fFetchResponseIndex = 0;
   numberOfCharsInThisChunk = 0;
   charsReadSoFar = 0;
+  fServerUnavailable = false;
 }

 nsImapServerResponseParser::~nsImapServerResponseParser() {
@@ -1573,13 +1574,18 @@ void nsImapServerResponseParser::resp_text_code() {
     AdvanceToNextToken();

   if (ContinueParse()) {
-    if (!PL_strcasecmp(fNextToken, "ALERT]")) {
-      char* alertMsg = fCurrentTokenPlaceHolder;  // advance past ALERT]
+    if (!PL_strcasecmp(fNextToken, "ALERT]") ||
+        !PL_strcasecmp(fNextToken, "UNAVAILABLE]")) {
+      // Treat ALERT and UNAVAILABLE response codes similarly. Show response
+      // code string in pop-up. See RFC 5530 "IMAP Response Codes".
+      char* alertMsg = fCurrentTokenPlaceHolder;  // advance past ALERT/UNAVAIL
       if (alertMsg && *alertMsg &&
           (!fLastAlert || PL_strcmp(fNextToken, fLastAlert))) {
         fServerConnection.AlertUserEvent(alertMsg);
         PR_Free(fLastAlert);
         fLastAlert = PL_strdup(alertMsg);
+        // If UNAVAILABLE, flag this to prevent a possible password prompt
+        fServerUnavailable = (NS_ToUpper(fNextToken[0]) == 'U');
       }
       AdvanceToNextToken();
     } else if (!PL_strcasecmp(fNextToken, "PARSE]")) {
